#include <stdio.h>

int main(void) {
    int choice = 0;

    if (scanf("%d", &choice) != 1) {
        return 1;
    }

    switch (choice) {
        case 1:
            printf("我们要一条三文鱼\n");
            break;
        case 2:
            printf("我们要一条秋刀鱼\n");
            break;
        case 3:
            printf("我们要一条鳕鱼\n");
            break;
        default:
            printf("这个编号我们不认识\n");
            break;
    }
    return 0;
}

